  'tool3-con1' => 'Անվճար մակարդակը կարող է սահմանափակել ֆայլի չափը կամ խմբաքանակի քանակը',
  'tool3-con2' => 'Որոշ գործիքներ պահանջում են հաշիվ ստեղծել',
  'tool3-con3' => 'Միաձուլման առաջադեմ գործառույթները հասանելի են աշխատասեղանի հավելվածում',
